package hotel.reports;

import hotel.reservations.Reservation;
import hotel.reservations.ReservationStore;
import hotel.rooms.Room;
import hotel.rooms.Rooms;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** Which rooms are occupied on a given night, for the front desk (CSV). */
public final class OccupancyReport {

    private final Rooms rooms;
    private final ReservationStore store;

    public OccupancyReport(Rooms rooms, ReservationStore store) {
        this.rooms = rooms;
        this.store = store;
    }

    public String generate(LocalDate night) {
        List<Reservation> occupying = new ArrayList<>();
        for (Reservation reservation : store.all()) {
            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
            if (reservation.isPaid() && coversNight) {
                occupying.add(reservation);
            }
        }
        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));

        StringBuilder csv = new StringBuilder();
        csv.append("room,type,reservation,check_in,check_out\n");
        for (Reservation reservation : occupying) {
            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
            csv.append(room.number()).append(',')
                    .append(room.type()).append(',')
                    .append(reservation.id()).append(',')
                    .append(reservation.checkIn()).append(',')
                    .append(reservation.checkOut()).append('\n');
        }
        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
        return csv.toString();
    }
}
package hotel.reports;

import hotel.reservations.Reservation;
import hotel.reservations.ReservationStore;
import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
 */
public final class RevenueReport {

    private final ReservationStore store;

    public RevenueReport(ReservationStore store) {
        this.store = store;
    }

    public String generate(YearMonth month) {
        List<Reservation> withRevenue = new ArrayList<>();
        for (Reservation reservation : store.all()) {
            boolean keptMoney = reservation.amountKept().signum() > 0;
            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
            if (keptMoney && startsInMonth) {
                withRevenue.add(reservation);
            }
        }
        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));

        StringBuilder csv = new StringBuilder();
        csv.append("reservation,room,check_in,check_out,status,amount\n");
        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
        for (Reservation reservation : withRevenue) {
            csv.append(reservation.id()).append(',')
                    .append(reservation.roomNumber()).append(',')
                    .append(reservation.checkIn()).append(',')
                    .append(reservation.checkOut()).append(',')
                    .append(reservation.status()).append(',')
                    .append(reservation.amountKept().toPlainString()).append('\n');
            revenue = revenue.add(reservation.amountKept());
        }
        csv.append("total,").append(revenue.toPlainString()).append('\n');
        return csv.toString();
    }
}
package hotel.web;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import hotel.messages.SentMessages;
import hotel.reports.OccupancyReport;
import hotel.reports.RevenueReport;
import hotel.reservations.ErrorCode;
import hotel.reservations.Guest;
import hotel.reservations.HotelException;
import hotel.reservations.NewReservation;
import hotel.reservations.ReservationService;
import hotel.rooms.Rooms;
import io.javalin.Javalin;
import io.javalin.http.Context;
import io.javalin.json.JavalinJackson;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeParseException;

/** The HTTP API the inn's website and front desk call. */
public final class HttpApi {

    private final Javalin server;
    private final Rooms rooms;
    private final ReservationService reservations;
    private final SentMessages sentMessages;
    private final OccupancyReport occupancyReport;
    private final RevenueReport revenueReport;

    public HttpApi(
            Rooms rooms,
            ReservationService reservations,
            SentMessages sentMessages,
            OccupancyReport occupancyReport,
            RevenueReport revenueReport) {
        this.rooms = rooms;
        this.reservations = reservations;
        this.sentMessages = sentMessages;
        this.occupancyReport = occupancyReport;
        this.revenueReport = revenueReport;

        ObjectMapper jsonMapper = JsonMapper.builder()
                .addModule(new JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
                .build();
        this.server = Javalin.create(config -> {
            config.showJavalinBanner = false;
            config.jsonMapper(new JavalinJackson(jsonMapper, false));
        });
        registerRoutes();
        registerErrorHandling();
    }

    public Javalin server() {
        return server;
    }

    private void registerRoutes() {
        server.get("/rooms", ctx -> ctx.json(rooms.all()));

        server.post("/reservations", ctx -> {
            NewReservation request = readNewReservation(ctx);
            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
        });
        server.get("/reservations/{id}", ctx ->
                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
        server.post("/reservations/{id}/confirmation", ctx ->
                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
        server.post("/reservations/{id}/cancellation", ctx ->
                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
        server.post("/reservations/{id}/check-in", ctx ->
                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
        server.post("/reservations/{id}/check-out", ctx ->
                ctx.json(reservations.checkOut(reservationId(ctx))));
        server.get("/reservations/{id}/document", ctx ->
                ctx.json(reservations.receiptCopy(reservationId(ctx))));

        server.get("/messages", ctx -> ctx.json(sentMessages.all()));

        server.get("/reports/occupancy", ctx -> {
            LocalDate night = readDate(ctx);
            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
        });
        server.get("/reports/revenue", ctx -> {
            YearMonth month = readMonth(ctx);
            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
        });
    }

    private void registerErrorHandling() {
        server.exception(HotelException.class, (exception, ctx) -> {
            ctx.status(httpStatus(exception.errorCode()));
            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
        });
    }

    private static int httpStatus(ErrorCode errorCode) {
        return switch (errorCode) {
            case INVALID_REQUEST -> 400;
            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
            case CAPACITY_EXCEEDED -> 422;
        };
    }

    private static NewReservation readNewReservation(Context ctx) {
        CreateReservationRequest body;
        try {
            body = ctx.bodyAsClass(CreateReservationRequest.class);
        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
        }
        if (body == null
                || body.roomNumber() == null
                || isBlank(body.guestName())
                || isBlank(body.guestEmail())
                || isBlank(body.guestCpf())
                || body.checkIn() == null
                || body.checkOut() == null
                || body.guests() == null
                || body.ratePlan() == null) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
        }
        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
        return new NewReservation(
                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
    }

    private static long reservationId(Context ctx) {
        String id = ctx.pathParam("id");
        try {
            return Long.parseLong(id);
        } catch (NumberFormatException notANumber) {
            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
        }
    }

    private static LocalDate readDate(Context ctx) {
        String date = requiredQueryParam(ctx, "date");
        try {
            return LocalDate.parse(date);
        } catch (DateTimeParseException badDate) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
        }
    }

    private static YearMonth readMonth(Context ctx) {
        String month = requiredQueryParam(ctx, "month");
        try {
            return YearMonth.parse(month);
        } catch (DateTimeParseException badMonth) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
        }
    }

    private static String requiredQueryParam(Context ctx, String name) {
        String value = ctx.queryParam(name);
        if (value == null) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
        }
        return value;
    }

    private static boolean isBlank(String text) {
        return text == null || text.isBlank();
    }
}
package hotel.reservations;

import java.math.BigDecimal;
import java.time.LocalDate;

public final class Reservation {

    private final long id;
    private final int roomNumber;
    private final Guest guest;
    private final LocalDate checkIn;
    private final LocalDate checkOut;
    private final int guests;
    private final RatePlan ratePlan;
    private final Price price;
    private ReservationStatus status;
    private BigDecimal amountPaid;
    private BigDecimal refund;

    Reservation(long id, NewReservation request, Price price) {
        this(id, request, price, ReservationStatus.PENDING, PriceCalculator.cents(BigDecimal.ZERO), null);
    }

    Reservation(
            long id,
            NewReservation request,
            Price price,
            ReservationStatus status,
            BigDecimal amountPaid,
            BigDecimal refund) {
        this.id = id;
        this.roomNumber = request.roomNumber();
        this.guest = request.guest();
        this.checkIn = request.checkIn();
        this.checkOut = request.checkOut();
        this.guests = request.guests();
        this.ratePlan = request.ratePlan();
        this.price = price;
        this.status = status;
        this.amountPaid = amountPaid;
        this.refund = refund;
    }

    public long id() {
        return id;
    }

    public int roomNumber() {
        return roomNumber;
    }

    public Guest guest() {
        return guest;
    }

    public LocalDate checkIn() {
        return checkIn;
    }

    public LocalDate checkOut() {
        return checkOut;
    }

    public int guests() {
        return guests;
    }

    public RatePlan ratePlan() {
        return ratePlan;
    }

    public Price price() {
        return price;
    }

    public ReservationStatus status() {
        return status;
    }

    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
    public BigDecimal amountPaid() {
        return amountPaid;
    }

    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
    public BigDecimal refund() {
        return refund;
    }

    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
    public boolean isPaid() {
        return status == ReservationStatus.CONFIRMED
                || status == ReservationStatus.CHECKED_IN
                || status == ReservationStatus.CHECKED_OUT;
    }

    /** The money the inn keeps from this reservation. */
    public BigDecimal amountKept() {
        return refund == null ? amountPaid : amountPaid.subtract(refund);
    }

    void changeStatus(ReservationStatus newStatus) {
        this.status = newStatus;
    }

    void confirmPayment() {
        this.status = ReservationStatus.CONFIRMED;
        this.amountPaid = price.total();
    }

    void cancel(BigDecimal refundAmount) {
        this.status = ReservationStatus.CANCELLED;
        this.refund = refundAmount;
    }
}
package hotel.reservations;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import javax.sql.DataSource;

/** Keeps the reservations in the database. */
public final class ReservationStore {

    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
    private static final String EXCLUSION_VIOLATION = "23P01";

    private final DataSource dataSource;

    public ReservationStore(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    /** Saves a new reservation; the database numbers it. */
    Reservation add(NewReservation request, Price price) {
        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
        try (Connection connection = dataSource.getConnection();
                PreparedStatement statement = connection.prepareStatement(insert)) {
            statement.setInt(1, request.roomNumber());
            statement.setString(2, request.guest().name());
            statement.setString(3, request.guest().email());
            statement.setString(4, request.guest().cpf());
            statement.setDate(5, Date.valueOf(request.checkIn()));
            statement.setDate(6, Date.valueOf(request.checkOut()));
            statement.setInt(7, request.guests());
            statement.setString(8, request.ratePlan().name());
            statement.setInt(9, price.nights());
            statement.setBigDecimal(10, price.subtotal());
            statement.setBigDecimal(11, price.discount());
            statement.setBigDecimal(12, price.total());
            statement.setString(13, ReservationStatus.PENDING.name());
            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
            try (ResultSet generated = statement.executeQuery()) {
                generated.next();
                return new Reservation(generated.getLong("id"), request, price);
            }
        } catch (SQLException failure) {
            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
                        "room " + request.roomNumber() + " is taken on some of those nights");
            }
            throw new IllegalStateException("could not save the reservation", failure);
        }
    }

    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
    void update(Reservation reservation) {
        try (Connection connection = dataSource.getConnection();
                PreparedStatement statement = connection.prepareStatement(
                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
            statement.setString(1, reservation.status().name());
            statement.setBigDecimal(2, reservation.amountPaid());
            statement.setBigDecimal(3, reservation.refund());
            statement.setLong(4, reservation.id());
            statement.executeUpdate();
        } catch (SQLException failure) {
            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
        }
    }

    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
        try (Connection connection = dataSource.getConnection();
                PreparedStatement select = connection.prepareStatement(
                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
                                + "AND check_in < ? AND ? < check_out")) {
            select.setInt(1, roomNumber);
            select.setDate(2, Date.valueOf(checkOut));
            select.setDate(3, Date.valueOf(checkIn));
            try (ResultSet rows = select.executeQuery()) {
                return rows.next();
            }
        } catch (SQLException failure) {
            throw new IllegalStateException("could not check room " + roomNumber, failure);
        }
    }

    public Optional<Reservation> find(long id) {
        try (Connection connection = dataSource.getConnection();
                PreparedStatement select = connection.prepareStatement(
                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
            select.setLong(1, id);
            try (ResultSet rows = select.executeQuery()) {
                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
            }
        } catch (SQLException failure) {
            throw new IllegalStateException("could not read reservation " + id, failure);
        }
    }

    public List<Reservation> all() {
        try (Connection connection = dataSource.getConnection();
                PreparedStatement select = connection.prepareStatement(
                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
                ResultSet rows = select.executeQuery()) {
            List<Reservation> reservations = new ArrayList<>();
            while (rows.next()) {
                reservations.add(read(rows));
            }
            return reservations;
        } catch (SQLException failure) {
            throw new IllegalStateException("could not read the reservations", failure);
        }
    }

    private static Reservation read(ResultSet row) throws SQLException {
        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"));
        NewReservation request = new NewReservation(
                row.getInt("room_number"),
                guest,
                row.getDate("check_in").toLocalDate(),
                row.getDate("check_out").toLocalDate(),
                row.getInt("guests"),
                RatePlan.valueOf(row.getString("rate_plan")));
        Price price = new Price(
                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
                row.getBigDecimal("total"));
        return new Reservation(
                row.getLong("id"),
                request,
                price,
                ReservationStatus.valueOf(row.getString("status")),
                row.getBigDecimal("amount_paid"),
                row.getBigDecimal("refund"));
    }
}
