    public String generate(YearMonth month) {
        CsvReport csv = new CsvReport("revenue", month, "reservation,room,check_in,check_out,status,amount");
        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
        for (Reservation reservation : withRevenue(store, month)) {
            csv.line(reservation.id(), reservation.roomNumber(), reservation.checkIn(), reservation.checkOut(),
                    reservation.status(), reservation.amountKept().toPlainString());
            revenue = revenue.add(reservation.amountKept());
        }
        csv.line("total", revenue.toPlainString());
        return csv.build();
    }

    /** The reservations this report counts, in the order it lists them. */
    static List<Reservation> withRevenue(ReservationStore store, YearMonth month) {
        List<Reservation> withRevenue = new ArrayList<>();
        for (Reservation reservation : store.all()) {
            boolean keptMoney = reservation.amountKept().signum() > 0;
            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
            if (keptMoney && startsInMonth) {
                withRevenue.add(reservation);
            }
        }
        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
        return withRevenue;
    }
}
